/**
 * T22/C10 boundary validation: generated JSON Schemas + Ajv (docs/18 §3).
 *
 * `shared/contracts/ts/contracts.ts` is generated by `scripts/schema-ts.py` from the Rust contract
 * crates; never edit it. These validators are the first gate at the IPC/HTTP/SSE boundary; the
 * field-level readers in `protocol.ts` remain as secondary checks and for mapping.
 *
 * Ajv hardening (C19 round-2 review P2):
 * - `strict: true` makes unknown keywords/formats a **compile-time error** instead of being silently
 *   ignored (`strictSchema`); our own boundary schemas must compile, otherwise the module fails fast.
 * - Schemars emits numeric formats (`uint8/16/32/64`, `int*`, `float/double`) that JSON Schema/Ajv do
 *   not know; they are registered below with explicit numeric semantics (safe-integer bounds, finite
 *   doubles). Format names we do not register are rejected, so a future schema must register its format
 *   here instead of silently dropping the check (C10 false-green guard).
 * - `additionalProperties` is intentionally **not** `false` (schemars default; docs/04:257: network DTOs
 *   do not deny unknown fields so old clients can parse new servers; docs/18 §5: "未知字段兼容 → 前端
 *   schema 允许 unknown"). Unknown settings/event fields are therefore accepted and ignored by the
 *   mapping functions; do not add `deny_unknown_fields`/`additionalProperties:false` without an ADR.
 */
import Ajv, { type ValidateFunction } from "ajv";
import {
  agent_eventSchema,
  agent_question_askedSchema,
  app_settingsSchema,
  conversationSchema,
  ipc_attachment_save_resultSchema,
  ipc_chat_send_resultSchema,
  ipc_command_responseSchema,
  ipc_eventSchema,
  compact_resultSchema,
  compaction_get_resultSchema,
  plan_get_resultSchema,
  plan_update_resultSchema,
  conversation_override_resultSchema,
  feedback_submit_resultSchema,
  goal_resultSchema,
  ipc_meta_infoSchema,
  ipc_terminal_resultSchema,
  session_messageSchema,
  session_export_resultSchema,
  session_search_resultSchema,
  workspace_file_read_resultSchema,
  workspace_changes_resultSchema,
  workspace_files_resultSchema,
  workspaceSchema,
} from "../../../../shared/contracts/ts/contracts";

/** Numeric formats emitted by schemars; explicit semantics instead of silent ignore. */
const NUMERIC_FORMATS: Record<string, (value: number) => boolean> = {
  uint8: (value) => Number.isInteger(value) && value >= 0 && value <= 0xff,
  uint16: (value) => Number.isInteger(value) && value >= 0 && value <= 0xffff,
  uint32: (value) => Number.isInteger(value) && value >= 0 && value <= 0xffff_ffff,
  uint64: (value) => Number.isSafeInteger(value) && value >= 0,
  uint: (value) => Number.isSafeInteger(value) && value >= 0,
  int8: (value) => Number.isInteger(value) && value >= -0x80 && value <= 0x7f,
  int16: (value) => Number.isInteger(value) && value >= -0x8000 && value <= 0x7fff,
  int32: (value) => Number.isInteger(value) && value >= -0x8000_0000 && value <= 0x7fff_ffff,
  int64: (value) => Number.isSafeInteger(value),
  int: (value) => Number.isSafeInteger(value),
  float: (value) => Number.isFinite(value),
  double: (value) => Number.isFinite(value),
};

/**
 * Compiles the production boundary Ajv instance. Exported for the strictness regression tests.
 * `strict: true` + registered formats means an unknown keyword/format throws at compile time.
 */
export function createBoundaryAjv(): Ajv {
  const ajv = new Ajv({ allErrors: true, strict: true, logger: false });
  for (const [name, validate] of Object.entries(NUMERIC_FORMATS)) {
    ajv.addFormat(name, { type: "number", validate });
  }
  return ajv;
}

const ajv = createBoundaryAjv();

export type BoundaryName =
  | "commandResponse"
  | "uiEvent"
  | "agentEvent"
  | "appSettings"
  | "workspace"
  | "conversation"
  | "message"
  | "metaInfo"
  | "chatSendResult"
  | "workspaceFilesResult"
  | "workspaceChangesResult"
  | "attachmentSaveResult"
  | "workspaceFileReadResult"
  | "sessionSearchResult"
  | "terminalResult"
  | "goalResult"
  | "conversationOverrideResult"
  | "sessionExportResult"
  | "compactResult"
  | "compactionGetResult"
  | "planGetResult"
  | "planUpdateResult"
  | "feedbackSubmitResult"
  | "questionAsked";

const checks: Record<BoundaryName, ValidateFunction> = {
  commandResponse: ajv.compile(ipc_command_responseSchema),
  uiEvent: ajv.compile(ipc_eventSchema),
  agentEvent: ajv.compile(agent_eventSchema),
  appSettings: ajv.compile(app_settingsSchema),
  workspace: ajv.compile(workspaceSchema),
  conversation: ajv.compile(conversationSchema),
  message: ajv.compile(session_messageSchema),
  metaInfo: ajv.compile(ipc_meta_infoSchema),
  chatSendResult: ajv.compile(ipc_chat_send_resultSchema),
  workspaceFilesResult: ajv.compile(workspace_files_resultSchema),
  workspaceChangesResult: ajv.compile(workspace_changes_resultSchema),
  attachmentSaveResult: ajv.compile(ipc_attachment_save_resultSchema),
  workspaceFileReadResult: ajv.compile(workspace_file_read_resultSchema),
  sessionSearchResult: ajv.compile(session_search_resultSchema),
  terminalResult: ajv.compile(ipc_terminal_resultSchema),
  goalResult: ajv.compile(goal_resultSchema),
  conversationOverrideResult: ajv.compile(conversation_override_resultSchema),
  sessionExportResult: ajv.compile(session_export_resultSchema),
  feedbackSubmitResult: ajv.compile(feedback_submit_resultSchema),
  compactResult: ajv.compile(compact_resultSchema),
  compactionGetResult: ajv.compile(compaction_get_resultSchema),
  planGetResult: ajv.compile(plan_get_resultSchema),
  planUpdateResult: ajv.compile(plan_update_resultSchema),
  questionAsked: ajv.compile(agent_question_askedSchema),
};

function describe(errors: ValidateFunction["errors"]): string {
  if (errors === null || errors === undefined) {
    return "";
  }
  return errors
    .slice(0, 3)
    .map((error) => `${error.instancePath === "" ? "/" : error.instancePath} ${error.message ?? ""}`.trim())
    .join("; ");
}

/** Returns true when `value` matches the generated schema; logs a bounded warning on failure. */
export function validateBoundary(name: BoundaryName, value: unknown): boolean {
  const check = checks[name];
  if (check(value)) {
    return true;
  }
  console.warn(`[zk] schema validation failed: ${name}`, describe(check.errors));
  return false;
}

export function validateCommandResponse(value: unknown): boolean {
  return validateBoundary("commandResponse", value);
}

